-- ════════════════════════════════════════════════════════════════════════════
--  Famous TechX POS — database schema for TiDB Cloud (MySQL-compatible)
--
--  Conventions
--   • Primary keys are UUID strings generated by the server (good for TiDB: no hotspots).
--   • Money DECIMAL(14,2), quantities DECIMAL(12,3). All times are UTC DATETIME(3).
--   • JSON is stored in TEXT columns and parsed by the server.
--   • The API server is the only writer; integrity rules live in the server's
--     transactions (SELECT … FOR UPDATE) plus the UNIQUE keys below.
--   • Run with:  npm run migrate   (idempotent — safe to re-run)
-- ════════════════════════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS schema_migrations (
  version VARCHAR(64) NOT NULL PRIMARY KEY,
  applied_at DATETIME(3) NOT NULL
);

-- ───────────── Accounts & sessions ─────────────
CREATE TABLE IF NOT EXISTS users (
  id CHAR(36) NOT NULL PRIMARY KEY,
  email VARCHAR(255) NULL,
  phone VARCHAR(32) NULL,
  full_name VARCHAR(200) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  must_change_password TINYINT(1) NOT NULL DEFAULT 0,
  created_at DATETIME(3) NOT NULL,
  UNIQUE (email)
);

CREATE TABLE IF NOT EXISTS sessions (
  id CHAR(36) NOT NULL PRIMARY KEY,
  token_hash CHAR(64) NOT NULL,
  user_id CHAR(36) NOT NULL,
  organization_id CHAR(36) NULL,
  member_id CHAR(36) NULL,
  method VARCHAR(10) NOT NULL,            -- password | pin
  terminal_id CHAR(36) NULL,
  created_at DATETIME(3) NOT NULL,
  last_seen_at DATETIME(3) NOT NULL,
  expires_at DATETIME(3) NOT NULL,
  revoked_at DATETIME(3) NULL,
  UNIQUE (token_hash)
);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions (user_id);

CREATE TABLE IF NOT EXISTS auth_tokens (
  token_hash CHAR(64) NOT NULL PRIMARY KEY,
  user_id CHAR(36) NOT NULL,
  member_id CHAR(36) NULL,                -- invite tokens are scoped to one business membership
  purpose VARCHAR(16) NOT NULL,           -- invite | reset
  expires_at DATETIME(3) NOT NULL,
  used_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL
);

-- ───────────── Business, branches, people ─────────────
CREATE TABLE IF NOT EXISTS subscription_plans (
  id VARCHAR(20) NOT NULL PRIMARY KEY,
  name VARCHAR(60) NOT NULL,
  max_members INT NOT NULL,
  max_branches INT NOT NULL
);

CREATE TABLE IF NOT EXISTS businesses (
  id CHAR(36) NOT NULL PRIMARY KEY,
  name VARCHAR(200) NOT NULL,
  category VARCHAR(60) NULL,
  phone VARCHAR(32) NULL,
  email VARCHAR(255) NULL,
  address VARCHAR(400) NULL,
  tin VARCHAR(40) NULL,
  registration_no VARCHAR(60) NULL,
  logo_url VARCHAR(1000) NULL,
  currency VARCHAR(3) NOT NULL DEFAULT 'GHS',
  timezone VARCHAR(60) NOT NULL DEFAULT 'Africa/Accra',
  settings TEXT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'active',
  owner_user_id CHAR(36) NOT NULL,
  plan_id VARCHAR(20) NOT NULL DEFAULT 'business',
  created_at DATETIME(3) NOT NULL,
  updated_at DATETIME(3) NOT NULL
);

CREATE TABLE IF NOT EXISTS branches (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  name VARCHAR(160) NOT NULL,
  code VARCHAR(8) NOT NULL,
  address VARCHAR(400) NULL,
  phone VARCHAR(32) NULL,
  status VARCHAR(10) NOT NULL DEFAULT 'active',
  is_default TINYINT(1) NOT NULL DEFAULT 0,
  created_at DATETIME(3) NOT NULL
);
CREATE INDEX IF NOT EXISTS branches_org ON branches (organization_id);

CREATE TABLE IF NOT EXISTS permissions (
  perm_key VARCHAR(40) NOT NULL PRIMARY KEY,
  label VARCHAR(120) NOT NULL,
  module VARCHAR(40) NOT NULL,
  sensitive TINYINT(1) NOT NULL DEFAULT 0,
  sort INT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS roles (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  role_key VARCHAR(40) NOT NULL,
  name VARCHAR(80) NOT NULL,
  description VARCHAR(300) NOT NULL DEFAULT '',
  is_system TINYINT(1) NOT NULL DEFAULT 0,
  max_discount_percent DECIMAL(5,2) NOT NULL DEFAULT 0,
  max_refund_amount DECIMAL(14,2) NOT NULL DEFAULT 0,
  allow_no_sale TINYINT(1) NOT NULL DEFAULT 0,
  created_at DATETIME(3) NOT NULL,
  UNIQUE (organization_id, role_key)
);

CREATE TABLE IF NOT EXISTS role_permissions (
  role_id CHAR(36) NOT NULL,
  perm_key VARCHAR(40) NOT NULL,
  PRIMARY KEY (role_id, perm_key)
);

CREATE TABLE IF NOT EXISTS business_members (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  user_id CHAR(36) NOT NULL,
  role_id CHAR(36) NOT NULL,
  full_name VARCHAR(200) NOT NULL,
  display_name VARCHAR(80) NOT NULL,
  email VARCHAR(255) NULL,
  phone VARCHAR(32) NULL,
  employee_code VARCHAR(20) NOT NULL,
  status VARCHAR(12) NOT NULL DEFAULT 'invited',   -- invited | active | suspended | deactivated
  is_owner TINYINT(1) NOT NULL DEFAULT 0,
  hire_date DATE NULL,
  avatar_color VARCHAR(40) NOT NULL DEFAULT 'bg-brand-600',
  pin_hash VARCHAR(255) NULL,                      -- never returned by the API
  pin_failed INT NOT NULL DEFAULT 0,
  pin_locked_until DATETIME(3) NULL,
  last_sign_in_at DATETIME(3) NULL,
  deactivated_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL,
  UNIQUE (organization_id, user_id),
  UNIQUE (organization_id, employee_code)
);
CREATE INDEX IF NOT EXISTS members_user ON business_members (user_id);
CREATE INDEX IF NOT EXISTS members_phone ON business_members (phone);

CREATE TABLE IF NOT EXISTS member_branch_access (
  member_id CHAR(36) NOT NULL,
  branch_id CHAR(36) NOT NULL,
  PRIMARY KEY (member_id, branch_id)
);

CREATE TABLE IF NOT EXISTS member_permission_overrides (
  member_id CHAR(36) NOT NULL,
  perm_key VARCHAR(40) NOT NULL,
  effect VARCHAR(8) NOT NULL,                      -- grant | revoke
  PRIMARY KEY (member_id, perm_key)
);

-- ───────────── Tills ─────────────
CREATE TABLE IF NOT EXISTS pos_terminals (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  branch_id CHAR(36) NOT NULL,
  name VARCHAR(80) NOT NULL,
  code VARCHAR(8) NOT NULL,
  token_hash CHAR(64) NOT NULL,
  status VARCHAR(10) NOT NULL DEFAULT 'active',
  registered_by CHAR(36) NULL,
  last_seen_at DATETIME(3) NULL,
  receipt_seq INT NOT NULL DEFAULT 0,
  created_at DATETIME(3) NOT NULL,
  UNIQUE (token_hash)
);

CREATE TABLE IF NOT EXISTS sign_in_events (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  member_id CHAR(36) NOT NULL,
  terminal_id CHAR(36) NULL,
  method VARCHAR(10) NOT NULL,
  success TINYINT(1) NOT NULL,
  device VARCHAR(120) NULL,
  created_at DATETIME(3) NOT NULL
);
CREATE INDEX IF NOT EXISTS signins_member ON sign_in_events (member_id, created_at);
CREATE INDEX IF NOT EXISTS signins_org ON sign_in_events (organization_id, created_at);

-- ───────────── Catalogue & stock ─────────────
CREATE TABLE IF NOT EXISTS categories (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  name VARCHAR(80) NOT NULL,
  color VARCHAR(60) NOT NULL,
  created_at DATETIME(3) NOT NULL,
  UNIQUE (organization_id, name)
);

CREATE TABLE IF NOT EXISTS products (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  category_id CHAR(36) NULL,
  name VARCHAR(200) NOT NULL,
  brand VARCHAR(120) NULL,
  description TEXT NULL,
  image_url VARCHAR(1000) NULL,
  sku VARCHAR(64) NOT NULL,
  barcode VARCHAR(64) NULL,
  cost_price DECIMAL(14,2) NOT NULL DEFAULT 0,
  selling_price DECIMAL(14,2) NOT NULL,
  unit VARCHAR(10) NOT NULL DEFAULT 'pc',          -- 'job' = service (not stock-tracked)
  taxable TINYINT(1) NOT NULL DEFAULT 1,
  reorder_level DECIMAL(12,3) NOT NULL DEFAULT 0,
  status VARCHAR(10) NOT NULL DEFAULT 'active',
  created_at DATETIME(3) NOT NULL,
  updated_at DATETIME(3) NOT NULL,
  UNIQUE (organization_id, sku),
  UNIQUE (organization_id, barcode)
);

CREATE TABLE IF NOT EXISTS product_variants (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  product_id CHAR(36) NOT NULL,
  label VARCHAR(80) NOT NULL,
  sku VARCHAR(64) NOT NULL,
  barcode VARCHAR(64) NULL,
  selling_price DECIMAL(14,2) NULL,
  UNIQUE (organization_id, sku)
);
CREATE INDEX IF NOT EXISTS variants_product ON product_variants (product_id);

CREATE TABLE IF NOT EXISTS inventory (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  branch_id CHAR(36) NOT NULL,
  product_id CHAR(36) NOT NULL,
  variant_key CHAR(36) NOT NULL DEFAULT '',        -- '' = no variant
  quantity DECIMAL(12,3) NOT NULL DEFAULT 0,
  updated_at DATETIME(3) NOT NULL,
  UNIQUE (branch_id, product_id, variant_key)
);

CREATE TABLE IF NOT EXISTS stock_movements (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  branch_id CHAR(36) NOT NULL,
  product_id CHAR(36) NOT NULL,
  variant_id CHAR(36) NULL,
  movement_type VARCHAR(16) NOT NULL,
  quantity_delta DECIMAL(12,3) NOT NULL,
  quantity_before DECIMAL(12,3) NULL,
  quantity_after DECIMAL(12,3) NULL,
  reason VARCHAR(400) NULL,
  reference_type VARCHAR(30) NULL,
  reference_id CHAR(36) NULL,
  actor_id CHAR(36) NULL,
  created_at DATETIME(3) NOT NULL
);
CREATE INDEX IF NOT EXISTS movements_branch ON stock_movements (branch_id, created_at);

CREATE TABLE IF NOT EXISTS barcode_cache (
  barcode VARCHAR(64) NOT NULL PRIMARY KEY,
  data TEXT NULL,
  found TINYINT(1) NOT NULL,
  fetched_at DATETIME(3) NOT NULL
);

-- ───────────── Customers ─────────────
CREATE TABLE IF NOT EXISTS customers (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  name VARCHAR(200) NOT NULL,
  phone VARCHAR(32) NULL,
  email VARCHAR(255) NULL,
  address VARCHAR(400) NULL,
  notes TEXT NULL,
  status VARCHAR(10) NOT NULL DEFAULT 'active',
  total_spend DECIMAL(14,2) NOT NULL DEFAULT 0,
  visits INT NOT NULL DEFAULT 0,
  last_visit_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL
);
CREATE INDEX IF NOT EXISTS customers_org ON customers (organization_id, name);

-- ───────────── Shifts, approvals, cash ─────────────
CREATE TABLE IF NOT EXISTS shifts (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  branch_id CHAR(36) NOT NULL,
  terminal_id CHAR(36) NOT NULL,
  member_id CHAR(36) NOT NULL,
  status VARCHAR(8) NOT NULL DEFAULT 'open',
  opening_float DECIMAL(14,2) NOT NULL DEFAULT 0,
  expected_cash DECIMAL(14,2) NULL,
  counted_cash DECIMAL(14,2) NULL,
  denomination_counts TEXT NULL,
  variance DECIMAL(14,2) NULL,
  note VARCHAR(500) NULL,
  approved_by CHAR(36) NULL,
  opened_at DATETIME(3) NOT NULL,
  closed_at DATETIME(3) NULL,
  closed_by CHAR(36) NULL
);
CREATE INDEX IF NOT EXISTS shifts_terminal ON shifts (terminal_id, status);
CREATE INDEX IF NOT EXISTS shifts_branch ON shifts (branch_id, opened_at);

CREATE TABLE IF NOT EXISTS approvals (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  terminal_id CHAR(36) NULL,
  action VARCHAR(30) NOT NULL,
  amount DECIMAL(14,2) NULL,
  detail VARCHAR(500) NULL,
  requested_by CHAR(36) NOT NULL,
  approved_by CHAR(36) NOT NULL,
  used_at DATETIME(3) NULL,
  used_ref CHAR(36) NULL,
  created_at DATETIME(3) NOT NULL
);

CREATE TABLE IF NOT EXISTS cash_movements (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  shift_id CHAR(36) NOT NULL,
  type VARCHAR(10) NOT NULL,                       -- paid_in | paid_out | drop | no_sale
  amount DECIMAL(14,2) NOT NULL DEFAULT 0,
  reason VARCHAR(400) NOT NULL,
  actor_id CHAR(36) NOT NULL,
  approval_id CHAR(36) NULL,
  created_at DATETIME(3) NOT NULL
);
CREATE INDEX IF NOT EXISTS cashmoves_shift ON cash_movements (shift_id);

-- ───────────── Sales ─────────────
CREATE TABLE IF NOT EXISTS sales (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  branch_id CHAR(36) NOT NULL,
  terminal_id CHAR(36) NULL,
  shift_id CHAR(36) NULL,
  cashier_id CHAR(36) NOT NULL,
  customer_id CHAR(36) NULL,
  receipt_number VARCHAR(40) NOT NULL,
  idempotency_key VARCHAR(80) NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'completed', -- completed | partially_refunded | refunded | voided
  subtotal DECIMAL(14,2) NOT NULL,
  discount_total DECIMAL(14,2) NOT NULL DEFAULT 0,
  tax_total DECIMAL(14,2) NOT NULL DEFAULT 0,
  total DECIMAL(14,2) NOT NULL,
  paid_total DECIMAL(14,2) NOT NULL,
  change_due DECIMAL(14,2) NOT NULL DEFAULT 0,
  cost_total DECIMAL(14,2) NOT NULL DEFAULT 0,
  refunded_total DECIMAL(14,2) NOT NULL DEFAULT 0,
  discount_approval_id CHAR(36) NULL,
  void_reason VARCHAR(400) NULL,
  voided_by CHAR(36) NULL,
  voided_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL,
  UNIQUE (organization_id, receipt_number),
  UNIQUE (organization_id, idempotency_key)
);
CREATE INDEX IF NOT EXISTS sales_branch ON sales (branch_id, created_at);
CREATE INDEX IF NOT EXISTS sales_cashier ON sales (cashier_id, created_at);
CREATE INDEX IF NOT EXISTS sales_shift ON sales (shift_id);

CREATE TABLE IF NOT EXISTS sale_items (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  sale_id CHAR(36) NOT NULL,
  product_id CHAR(36) NOT NULL,
  variant_id CHAR(36) NULL,
  name_snapshot VARCHAR(260) NOT NULL,
  sku_snapshot VARCHAR(64) NOT NULL,
  quantity DECIMAL(12,3) NOT NULL,
  unit_price DECIMAL(14,2) NOT NULL,
  cost_snapshot DECIMAL(14,2) NOT NULL DEFAULT 0,
  discount DECIMAL(14,2) NOT NULL DEFAULT 0,
  tax DECIMAL(14,2) NOT NULL DEFAULT 0,
  line_total DECIMAL(14,2) NOT NULL,
  refunded_quantity DECIMAL(12,3) NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS saleitems_sale ON sale_items (sale_id);

CREATE TABLE IF NOT EXISTS payments (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  sale_id CHAR(36) NOT NULL,
  method VARCHAR(8) NOT NULL,                      -- cash | momo | card | bank
  amount DECIMAL(14,2) NOT NULL,
  status VARCHAR(10) NOT NULL DEFAULT 'recorded',
  provider_reference VARCHAR(120) NULL,
  recorded_by CHAR(36) NOT NULL,
  created_at DATETIME(3) NOT NULL
);
CREATE INDEX IF NOT EXISTS payments_sale ON payments (sale_id);

CREATE TABLE IF NOT EXISTS refunds (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  original_sale_id CHAR(36) NOT NULL,
  shift_id CHAR(36) NULL,
  amount DECIMAL(14,2) NOT NULL,
  method VARCHAR(8) NOT NULL,
  status VARCHAR(10) NOT NULL,
  reason VARCHAR(400) NOT NULL,
  restocked TINYINT(1) NOT NULL DEFAULT 0,
  actor_id CHAR(36) NOT NULL,
  approval_id CHAR(36) NULL,
  created_at DATETIME(3) NOT NULL
);
CREATE INDEX IF NOT EXISTS refunds_sale ON refunds (original_sale_id);

CREATE TABLE IF NOT EXISTS refund_items (
  id CHAR(36) NOT NULL PRIMARY KEY,
  refund_id CHAR(36) NOT NULL,
  sale_item_id CHAR(36) NOT NULL,
  quantity DECIMAL(12,3) NOT NULL,
  amount DECIMAL(14,2) NOT NULL
);

CREATE TABLE IF NOT EXISTS held_carts (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  branch_id CHAR(36) NOT NULL,
  terminal_id CHAR(36) NULL,
  owner_id CHAR(36) NOT NULL,
  note VARCHAR(300) NOT NULL DEFAULT '',
  cart_lines TEXT NOT NULL,
  created_at DATETIME(3) NOT NULL
);

-- ───────────── Purchasing & transfers ─────────────
CREATE TABLE IF NOT EXISTS suppliers (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  name VARCHAR(200) NOT NULL,
  phone VARCHAR(32) NULL,
  email VARCHAR(255) NULL,
  address VARCHAR(400) NULL,
  notes TEXT NULL,
  created_at DATETIME(3) NOT NULL
);

CREATE TABLE IF NOT EXISTS purchase_orders (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  branch_id CHAR(36) NOT NULL,
  supplier_id CHAR(36) NOT NULL,
  number VARCHAR(20) NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'draft',
  expected_at DATE NULL,
  supplier_reference VARCHAR(120) NULL,
  amount_paid DECIMAL(14,2) NOT NULL DEFAULT 0,
  created_by CHAR(36) NULL,
  created_at DATETIME(3) NOT NULL,
  UNIQUE (organization_id, number)
);

CREATE TABLE IF NOT EXISTS purchase_items (
  id CHAR(36) NOT NULL PRIMARY KEY,
  purchase_order_id CHAR(36) NOT NULL,
  product_id CHAR(36) NOT NULL,
  quantity DECIMAL(12,3) NOT NULL,
  received_quantity DECIMAL(12,3) NOT NULL DEFAULT 0,
  unit_cost DECIMAL(14,2) NOT NULL
);
CREATE INDEX IF NOT EXISTS purchaseitems_po ON purchase_items (purchase_order_id);

CREATE TABLE IF NOT EXISTS stock_transfers (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  number VARCHAR(20) NOT NULL,
  from_branch_id CHAR(36) NOT NULL,
  to_branch_id CHAR(36) NOT NULL,
  status VARCHAR(12) NOT NULL DEFAULT 'dispatched',
  note VARCHAR(400) NULL,
  dispatched_by CHAR(36) NULL,
  received_by CHAR(36) NULL,
  created_at DATETIME(3) NOT NULL,
  received_at DATETIME(3) NULL,
  UNIQUE (organization_id, number)
);

CREATE TABLE IF NOT EXISTS stock_transfer_items (
  transfer_id CHAR(36) NOT NULL,
  product_id CHAR(36) NOT NULL,
  quantity DECIMAL(12,3) NOT NULL,
  PRIMARY KEY (transfer_id, product_id)
);

-- ───────────── Expenses, notifications, audit ─────────────
CREATE TABLE IF NOT EXISTS expenses (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  branch_id CHAR(36) NOT NULL,
  category VARCHAR(60) NOT NULL,
  amount DECIMAL(14,2) NOT NULL,
  expense_date DATE NOT NULL,
  description VARCHAR(400) NOT NULL,
  method VARCHAR(8) NOT NULL DEFAULT 'cash',
  attachment_url VARCHAR(1000) NULL,
  status VARCHAR(10) NOT NULL DEFAULT 'recorded',
  void_reason VARCHAR(400) NULL,
  actor_id CHAR(36) NOT NULL,
  created_at DATETIME(3) NOT NULL
);
CREATE INDEX IF NOT EXISTS expenses_org ON expenses (organization_id, expense_date);

CREATE TABLE IF NOT EXISTS notifications (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  member_id CHAR(36) NULL,
  audience_perm VARCHAR(40) NULL,
  type VARCHAR(20) NOT NULL,
  title VARCHAR(200) NOT NULL,
  body VARCHAR(600) NOT NULL,
  read_by TEXT NULL,
  created_at DATETIME(3) NOT NULL
);
CREATE INDEX IF NOT EXISTS notifications_org ON notifications (organization_id, created_at);

CREATE TABLE IF NOT EXISTS audit_logs (
  id CHAR(36) NOT NULL PRIMARY KEY,
  organization_id CHAR(36) NOT NULL,
  branch_id CHAR(36) NULL,
  terminal_id CHAR(36) NULL,
  actor_id CHAR(36) NULL,
  category VARCHAR(12) NOT NULL,
  action VARCHAR(80) NOT NULL,
  detail VARCHAR(600) NOT NULL,
  amount DECIMAL(14,2) NULL,
  entity_type VARCHAR(30) NULL,
  entity_id CHAR(36) NULL,
  metadata TEXT NULL,
  created_at DATETIME(3) NOT NULL
);
CREATE INDEX IF NOT EXISTS audit_org ON audit_logs (organization_id, created_at);
CREATE INDEX IF NOT EXISTS audit_actor ON audit_logs (actor_id, created_at);

-- ───────────── Hot-path indexes (checkout, reports, history) ─────────────
-- These are safe to re-run; the migration executes schema.sql on every deploy.
CREATE INDEX IF NOT EXISTS sales_org_date ON sales (organization_id, created_at);
CREATE INDEX IF NOT EXISTS sales_org_branch_date ON sales (organization_id, branch_id, created_at);
CREATE INDEX IF NOT EXISTS sales_org_receipt ON sales (organization_id, receipt_number);
CREATE INDEX IF NOT EXISTS sale_items_sale ON sale_items (sale_id);
CREATE INDEX IF NOT EXISTS payments_sale ON payments (sale_id);
CREATE INDEX IF NOT EXISTS variants_org_barcode ON product_variants (organization_id, barcode);
CREATE INDEX IF NOT EXISTS inventory_product_branch ON inventory (product_id, branch_id);
CREATE INDEX IF NOT EXISTS movements_product ON stock_movements (product_id, created_at);
CREATE INDEX IF NOT EXISTS movements_org_date ON stock_movements (organization_id, created_at);
CREATE INDEX IF NOT EXISTS auth_tokens_user_purpose ON auth_tokens (user_id, purpose);
CREATE INDEX IF NOT EXISTS approvals_org_date ON approvals (organization_id, created_at);
CREATE INDEX IF NOT EXISTS refunds_org_date ON refunds (organization_id, created_at);
CREATE INDEX IF NOT EXISTS held_carts_org_branch_date ON held_carts (organization_id, branch_id, created_at);
CREATE INDEX IF NOT EXISTS purchase_orders_org_date ON purchase_orders (organization_id, created_at);
CREATE INDEX IF NOT EXISTS stock_transfers_org_date ON stock_transfers (organization_id, created_at);
CREATE INDEX IF NOT EXISTS terminals_org_branch ON pos_terminals (organization_id, branch_id);
CREATE INDEX IF NOT EXISTS customers_org_phone ON customers (organization_id, phone);
